<!doctype html><html lang="ja"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>コメント</title><style>body{font:15px/1.7 system-ui,sans-serif;color:#253b43;margin:16px}label{display:block;margin:12px 0}input,textarea{display:block;box-sizing:border-box;width:100%;font:inherit;border:1px solid #beced0;border-radius:6px;padding:8px}button{background:#12685c;color:white;border:0;padding:10px 20px;border-radius:6px;font:inherit}article{padding:12px 0;border-bottom:1px solid #ddd}.trap{position:absolute;left:-10000px}.error{color:#a12a2a}</style></head><body><h2>コメント</h2><?php if ($notice !== ''): ?><p role="status"><?= e($notice) ?></p><?php endif; ?><?php if ($error !== ''): ?><p role="alert" class="error"><?= e($error) ?></p><?php endif; ?><?php foreach ($rows as $row): ?><article><strong><?= e($row['name']) ?></strong> <time><?= e(date('Y-m-d', $row['created_at'])) ?></time><p><?= nl2br(e($row['body'])) ?></p></article><?php endforeach; ?><nav><?php if ($page > 1): ?><a href="?p=<?= $page - 1 ?>">前へ</a><?php endif; ?> <?php if (count($rows) === 50): ?><a href="?p=<?= $page + 1 ?>">次へ</a><?php endif; ?></nav><form method="post" action="<?= e(url('nx-multi-tool/comments/' . $type . '/' . $id)) ?>"><input type="hidden" name="_csrf_token" value="<?= e(\app\Core\Csrf::token()) ?>"><label>名前<input name="name" maxlength="120" required autocomplete="name"></label><label>メール（任意・公開しません）<input name="email" type="email" maxlength="254" autocomplete="email"></label><label class="trap" aria-hidden="true">Website<input name="website" tabindex="-1" autocomplete="off"></label><label>コメント（承認後に公開）<textarea name="body" rows="5" maxlength="8000" required></textarea></label><button type="submit">コメントを送信</button></form><script>new ResizeObserver(()=>parent.postMessage({type:'nxmt-comments-height',height:document.documentElement.scrollHeight},location.origin)).observe(document.body);</script></body></html>
